'use strict';

// MODULES //

var sqrt = require( '@stdlib/math/base/special/sqrt' );
var exp = require( '@stdlib/math/base/special/exp' );
var ln = require( '@stdlib/math/base/special/ln' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var r1 = require( './rational_p1q1.js' );
var p2 = require( './poly_p2.js' );
var r3 = require( './rational_p3q3.js' );


// VARIABLES //

var Y_SMALL = 1.137250900268554688;
var LOG_MAX = 709.782712893384;


// MAIN //

/**
* Computes the modified Bessel function of the second kind of order zero.
*
* ## Notes
*
* -   Accuracy for subnormal `x` is very poor. Full accuracy is achieved at approximately `1.0e-308` but degrades rapidly as `x → 0`.
*
* @param {number} x - input value
* @returns {number} evaluated Bessel function
*
* @example
* var v = k0( 0.0 );
* // returns Infinity
*
* @example
* var v = k0( 1.0 );
* // returns ~0.421
*
* @example
* var v = k0( 5.0 );
* // returns ~0.00369
*
* @example
* var v = k0( -1.0 );
* // returns NaN
*
* @example
* var v = k0( Infinity );
* // returns 0.0
*/
function k0( x ) {
	var ex;
	var a;

	if ( x < 0.0 ) {
		return NaN;
	}
	if ( x === 0.0 ) {
		return PINF;
	}
	if ( x === PINF ) {
		return 0.0;
	}

	// x <= 1
	if ( x <= 1.0 ) {
		a = ( x * x ) * 0.25;
		a = ( ( r1( a ) + Y_SMALL ) * a ) + 1.0;
		return p2( x * x ) - ( ln( x ) * a );
	}

	// x > 1
	if ( x < LOG_MAX ) {
		return ( r3( 1.0 / x ) + 1.0 ) *
			exp( -x ) / sqrt( x );
	}

	// overflow-safe
	ex = exp( -x * 0.5 );
	return ( r3( 1.0 / x ) + 1.0 ) *
		ex / sqrt( x ) * ex;
}


// EXPORTS //

module.exports = k0;
